"""Local isolated seller/SKU acceptance: page checkpoint restart, TID idempotence, conversion repair and UI chain."""
import json,time,subprocess,urllib.parse
from pathlib import Path
from datetime import datetime,timedelta
from verify_goods_workspace_ui import login,request,BASE
from test_multi_virtual_shipping import sql,quote,wait_for
from verify_queue_management import docker,wait_health
OUT=Path(__file__).resolve().parents[2]/'outputs/order-messaging';DB='qm_oms_saas_order';SRC='refund_acceptance_source';INV='qm_oms_saas_inventory'
def main():
 OUT.mkdir(parents=True,exist_ok=True);case={'stamp':datetime.now().strftime('%Y%m%d%H%M%S'),'checks':[]};token=login();original={};owned=False
 def save():(OUT/'case.json').write_text(json.dumps(case,ensure_ascii=False,indent=2),encoding='utf-8')
 def checked(value):case['checks'].append(value);save();print('PASS '+value,flush=True)
 def api(path,body=None,method=None):
  r=request(path,token=token,payload=body,method=method or ('POST' if body is not None else 'GET'));return r.get('data',r)
 def policy(kind):return api('/system/mqQueues/'+kind)
 def edit(kind,changes):r=policy(kind);r.update(changes);r['reason']='[订单队列验收] '+case['stamp'];return api('/system/mqQueues/'+kind,r,'PUT')
 def mode(kind,value):edit(kind,{'desired_mode':value});return wait_for(lambda:policy(kind),lambda r:r['effective_state']==value,'Queue configuration not applied: '+kind,300)
 def task(id):return api('/order/orders/tasks/'+str(id))
 def messages(kind,number):return api('/order/messages?type='+kind+'&keyword='+str(number))['rows']
 def message(kind,number):return messages(kind,number)[0]
 def goods(sku):
  sample=api('/goods/info/list?pageNum=1&pageSize=1',{})['rows'][0];api('/goods/info',{'skuSn':sku,'goodsSn':sku,'goodsName':'[订单队列验收] '+sku,'categoryCode':sample['categoryCode'],'colorCode':sample['colorCode'],'sizeCode':sample['sizeCode'],'marketPrice':1,'validity':30,'isPackage':0,'isFd':0})
 def seed(index,sku=None):
  tid='95'+case['stamp']+str(index).zfill(2);trade={'tid':tid,'status':'WAIT_SELLER_SEND_GOODS','type':'fixed','seller_nick':case['seller'],'oaid':'LOCAL-QUEUE-TEST','payment':'1.00','orders':{'order':[{'oid':tid+'1','num':1,'outer_sku_id':sku or case['sku'],'divide_order_fee':'1.00','title':'[队列验收] 商品'}]}};payload=json.dumps({'trade_fullinfo_get_response':{'trade':trade}},ensure_ascii=False)
  sql('INSERT INTO jdp_tb_trade(tid,status,type,seller_nick,created,modified,jdp_modified,jdp_response) VALUES ('+','.join(quote(v) for v in [tid,'WAIT_SELLER_SEND_GOODS','fixed',case['seller'],case['source_time'],case['source_time'],case['source_time'],payload])+')',SRC);return tid
 def backfill(body):return api('/order/orders/backfill',dict(body,channel_ids=[case['channel_id']]))['task_ids'][0]
 def query_platform(tid):return api('/order/orders/platform/list?tid='+str(tid))['rows'][0]
 def publish(envelope):
  body={'properties':{'delivery_mode':2,'content_type':'application/json','message_id':envelope['event_id']},'routing_key':envelope['message_type'],'payload':json.dumps(envelope),'payload_encoding':'string'}
  script="import sys,json,base64,urllib.request\nsys.path.insert(0,'docker/local')\nfrom local_db import ENV\nheaders={'Authorization':'Basic '+base64.b64encode((ENV['RABBITMQ_USER']+':'+ENV['RABBITMQ_PASSWORD']).encode()).decode(),'Content-Type':'application/json'}\nbody="+repr(body)+"\nr=urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:15672/api/exchanges/oms/oms.work.v1/publish',data=json.dumps(body).encode(),headers=headers),timeout=10)\nassert json.load(r)['routed']"
  r=subprocess.run(['wsl.exe','--','python3','-'],input=script.encode(),capture_output=True,timeout=20);assert r.returncode==0,'duplicate fixture publish failed'
 for service in ['oms-local-system','oms-local-channel','oms-local-order']:wait_health(service)
 try:
  original={k:policy(k) for k in ['ORDER_PULL','ORDER_CONVERT']};save();mode('ORDER_PULL','PAUSED');mode('ORDER_CONVERT','PAUSED')
  case['seller']='ORDER_QUEUE_'+case['stamp'];case['sku']='MQO'+case['stamp'];name='[订单队列验收] '+case['stamp'];api('/channel/channel',{'channelName':name,'channelType':'TM','enabled':1,'toChannelEnabled':1,'syncEnabled':0,'mmodelType':1});ch=api('/channel/channel/list?channelName='+urllib.parse.quote(name))['rows'][0]['channelId'];case['channel_id']=ch;source=next(s for s in api('/order/orders/sources') if s['database_name']==SRC and s['enabled']);assert source['host']=='mysql';now=datetime.now();case['start']=(now-timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S');case['end']=now.strftime('%Y-%m-%d %H:%M:%S');case['source_time']=(now-timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M:%S');save();api('/order/orders/configs',{'channel_id':ch,'source_key':source['source_key'],'seller_nick':case['seller'],'confirm_seller_mapping':1,'enabled':0,'auto_convert':1,'allowed_trade_types':['fixed'],'allow_public_stock':0,'interval_seconds':30,'initial_time':case['start']});goods(case['sku']);owned=True
  tids=[seed(i) for i in range(1,52)];case['tids']=tids;save();task_id=backfill({'mode':'TIME','start_time':case['start'],'end_time':case['end'],'request_key':'ORDER_QUEUE_'+case['stamp']});case['page_task']=task_id;save();r=task(task_id);assert r['message']['process_state']=='PENDING';assert int(sql('SELECT COUNT(*) FROM oms_platform_order WHERE company_code=0x514d AND channel_id='+str(ch),DB))==0;checked('paused pull retains durable task without reading source')
  mode('ORDER_PULL','RUNNING')
  deadline=time.time()+100
  while time.time()<deadline:
   r=task(task_id)
   if int(r['pulled_count'])>=50:break
   time.sleep(.15)
  assert int(r['pulled_count'])==50,'First page was not observed before second page';checkpoint=r['page_time'];cursor=r['page_tid'];docker('stop','--time','60','oms-local-order',timeout=90);assert int(sql('SELECT pulled_count FROM oms_order_pull_task WHERE company_code=0x514d AND id='+str(task_id),DB))==50
  docker('start','oms-local-order');wait_health('oms-local-order');r=wait_for(lambda:task(task_id),lambda r:r['status']=='SUCCESS','Pull did not resume after restart',180);assert int(r['pulled_count'])==51;case['checkpoint']={'page_time':checkpoint,'page_tid':cursor};assert int(sql('SELECT COUNT(*) FROM oms_platform_order WHERE company_code=0x514d AND channel_id='+str(ch),DB))==51;assert sql('SELECT COUNT(*) FROM oms_order WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='0';checked('51 source rows resume from committed page cursor after service restart; conversion remains separately paused')
  mode('ORDER_CONVERT','RUNNING');wait_for(lambda:sql('SELECT COUNT(*) FROM oms_order WHERE company_code=0x514d AND channel_id='+str(ch),DB),lambda n:n=='51','Conversion did not finish',240);first=query_platform(tids[0]);case['platform_id']=first['id'];case['order_id']=first['business_order_id'];detail=api('/order/orders/business/'+str(first['business_order_id']));case['order_sn']=detail['order_sn'];assert detail['inventory_status']=='WAIT_RESERVE';assert sql('SELECT COUNT(*) FROM oms_order_stock_demand WHERE company_code=0x514d AND channel_id='+str(ch),INV)=='51';m=message('ORDER_CONVERT',tids[0]);case['convert_event']=m['event_id'];save();env=api('/order/messages/'+m['event_id'])['envelope'];before=sql('SELECT COUNT(*) FROM oms_order_process_log WHERE company_code=0x514d AND platform_order_id='+str(first['id'])+" AND action='CONVERT' AND result='SUCCESS'",DB);publish(env);time.sleep(3);assert before==sql('SELECT COUNT(*) FROM oms_order_process_log WHERE company_code=0x514d AND platform_order_id='+str(first['id'])+" AND action='CONVERT' AND result='SUCCESS'",DB);assert sql('SELECT COUNT(*) FROM oms_order WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='51';checked('duplicate conversion notification does not create another business order or repeat conversion stock work')
  repeated=backfill({'mode':'TID','tids':[tids[0]],'request_key':'ORDER_TID_'+case['stamp']});wait_for(lambda:task(repeated),lambda r:r['status']=='SUCCESS','TID backfill not complete',120);assert sql('SELECT COUNT(*) FROM oms_platform_order WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='51';assert sql('SELECT COUNT(*) FROM oms_order WHERE company_code=0x514d AND channel_id='+str(ch),DB)=='51';case['tid_task']=repeated;checked('specified TID re-pull preserves platform identity and existing business order')
  bad='MQBAD'+case['stamp'];tid=seed(52,bad);failed=backfill({'mode':'TID','tids':[tid],'request_key':'ORDER_BAD_'+case['stamp']});wait_for(lambda:task(failed),lambda r:r['status']=='SUCCESS','Failed-conversion source task not complete',120);old=wait_for(lambda:messages('ORDER_CONVERT',tid),lambda rows:rows and rows[0]['process_state']=='FAILED','Conversion did not retain failure',150)[0];case['failed_tid']=tid;case['failed_event']=old['event_id'];goods(bad);api('/order/messages/'+old['event_id']+'/retry',{'reason':'[验收] 已补齐此模拟订单缺失的 OMS SKU'});latest=wait_for(lambda:message('ORDER_CONVERT',tid),lambda r:r['process_state']=='SUCCESS','Repaired conversion not complete',180);chain=api('/order/messages/'+old['event_id'])['chain'];assert chain[0]['event_id']==latest['event_id'] and chain[0]['parent_event_id']==old['event_id'];case['retry_event']=latest['event_id'];case['failed_pull_task']=failed;save();checked('source success and conversion failure remain distinct; repaired SKU retries original platform order with parent chain')
  from playwright.sync_api import sync_playwright,expect
  with sync_playwright() as p:
   b=p.chromium.launch(headless=True);ctx=b.new_context(viewport={'width':1800,'height':1150});ctx.add_cookies([{'name':'Admin-Token','value':token,'url':BASE}]);page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE+'/oms-order/management?tab=tasks&kind=ORDER&taskId='+str(task_id),wait_until='networkidle');expect(page.get_by_placeholder('配合业务类型精确查询')).to_have_value(str(task_id));expect(page.get_by_role('button',name='查看消息链路',exact=True).first).to_be_visible();page.screenshot(path=str(OUT/'intake-progress.png'),full_page=True,animations='disabled');page.get_by_role('button',name='查看消息链路',exact=True).first.click();expect(page.locator('.messages h2')).to_be_visible();expect(page.get_by_placeholder('全部业务类型')).to_have_value('订单拉取');page.locator('.el-table__fixed-right').get_by_role('button',name='详情 / 链路',exact=True).first.click();drawer=page.locator('.el-drawer:visible');drawer.get_by_role('button',name='打开业务单据',exact=True).click();expect(page.get_by_placeholder('配合业务类型精确查询')).to_have_value(str(task_id));page.goto(BASE+'/monitor/messages?service=order&type=ORDER_CONVERT&event='+old['event_id'],wait_until='networkidle');page.locator('.el-table__fixed-right').get_by_role('button',name='详情 / 链路',exact=True).first.click();expect(drawer.get_by_text('最新通知：处理完成',exact=False)).to_be_visible();page.screenshot(path=str(OUT/'conversion-retry-chain.png'),full_page=True,animations='disabled');drawer.get_by_role('button',name='打开业务单据',exact=True).click();expect(page.locator('.platform-documents')).to_be_visible();expect(page.get_by_role('button',name='查看消息链路',exact=True).first).to_be_visible();page.screenshot(path=str(OUT/'platform-progress.png'),full_page=True,animations='disabled');assert not errors,errors;b.close()
  checked('browser task filter, message progress, business return links and current conversion result');save()
 finally:
  docker('start','oms-local-order');wait_health('oms-local-order')
  for kind,r in original.items():edit(kind,{k:r[k] for k in ['desired_mode','concurrency','prefetch','retry_limit','retry_base_sec','retry_max_sec','compensate_after_sec','compensate_batch','app_rate','shop_rate','alarm_backlog','alarm_due_sec','alarm_failure_pct']})
 print('PASS order messaging acceptance retained at outputs/order-messaging/case.json',flush=True)
if __name__=='__main__':main()
